// Bento metrics grid — Nova Atelier
// 1. Composition: 2x2 bento (5.5x3.5u) — dominant 3.25x3.5 cell left (0.002 mm hero), two 2.0x1.625 cells stacked right; caption header above grid at x=-2.75; graded backdrop plane 7x6 at z=-2.5.
// 2. Light rig: rig-tech-clinical — key #f2f4f6 2.2 @ [1.6,3,2.6], fill #e6e9ee 1.5 @ [-2,2.4,2.2], rim #ffffff 1.0 @ [0,2,-3], ambient 0.34; accent red rim omitted (tick bars carry the accent).
// 3. Materials: slab faces MeshStandardNodeMaterial with TSL 135° engineered gradient #101017→#1a1a22 + hard-stop sheen band; chamfer frames brushed metal (rough 0.5, metal 0.45, physical clearcoat 0.2); tick bars emissive #ff2a38 @ 1.3.
// 4. Motion: stagger-cards fade-up entrance (y +0.2→0, 0.5s power2.out, 80ms stagger, dominant first); hover press-down 0.97/120ms back.out, release weighted-settle 1.04→1.0/0.9s power4.out; no idle multi-axis motion.
// 5. Focal: the dominant cell's "0.002 mm" valueLarge in paper #e8ecf2 — brightest read; everything else graded below it.

import {
  MeshStandardNodeMaterial,
  MeshPhysicalNodeMaterial,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import { uv, vec3, mix, smoothstep, step, add, float, color as tslColor } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const root = new THREE.Group();
  root.name = 'bento-metrics-grid';

  const geometries = [];
  const materials = [];
  const timelines = [];
  const primHandles = [];

  const spec = config.intent?.visualSpec ?? {};
  const colors = spec.colors ?? {};
  const C = {
    background: colors.background ?? '#0b0b10', // color.background
    surface: colors.surface ?? '#14141a',       // color.surface
    ink: colors.ink ?? '#16161d',               // color.ink
    paper: colors.paper ?? '#e8ecf2',           // color.paper
    accent: colors.accent ?? '#ff2a38',         // color.accent
    grad0: colors.gradientStops?.[0]?.hex ?? '#101017',
    grad1: colors.gradientStops?.[1]?.hex ?? '#1a1a22',
  };

  // ---------- backdropStage: graded stage plane, never a void ----------
  function backdropStage() {
    const geo = new THREE.PlaneGeometry(7, 6);
    geometries.push(geo);
    const mat = new MeshBasicNodeMaterial();
    const g0 = vec3(...hexToLin(C.background));
    const g1 = vec3(...hexToLin(C.grad1));
    // vertical gradient with subtle center lift so no flat #000 region
    const v = uv().y;
    const lift = smoothstep(0.15, 0.75, v).mul(0.85).add(smoothstep(0.0, 1.0, uv().x.sub(0.5).abs().oneMinus()).mul(0.15));
    mat.colorNode = mix(g0, g1, lift);
    materials.push(mat);
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.set(0, 0, -2.5);
    root.add(mesh);
  }

  function hexToLin(hex) {
    const c = new THREE.Color(hex);
    return [c.r, c.g, c.b];
  }

  // ---------- lightRig: rig-tech-clinical ----------
  function lightRig() {
    const amb = new THREE.AmbientLight('#e6e9ee', 0.34);
    root.add(amb);
    const key = new THREE.DirectionalLight('#f2f4f6', 1.2); // scene provides key 1.2; local trim below ceiling
    key.position.set(1.6, 3, 2.6);
    key.target.position.set(0, 0.4, 0);
    root.add(key, key.target);
    const fill = new THREE.DirectionalLight('#e6e9ee', 1.0);
    fill.position.set(-2, 2.4, 2.2);
    fill.target.position.set(0, 0.4, 0);
    root.add(fill, fill.target);
    const rim = new THREE.DirectionalLight('#ffffff', 0.8);
    rim.position.set(0, 2, -3);
    rim.target.position.set(0, 0.5, 0);
    root.add(rim, rim.target);
  }

  // ---------- slabFaceMaterial: engineered diagonal gradient + machined sheen band ----------
  function slabFaceMaterial() {
    const mat = new MeshStandardNodeMaterial({ roughness: 0.55, metalness: 0.35 });
    const g0 = vec3(...hexToLin(C.grad0));
    const g1 = vec3(...hexToLin(C.grad1));
    // 135-degree diagonal coordinate
    const d = uv().x.add(uv().y.oneMinus()).mul(0.5);
    let col = mix(g0, g1, d);
    // hard-stop machined sheen band ~0.15u wide at 40%, +6% value
    const band = step(0.4, d).mul(step(d, float(0.47)));
    col = mix(col, col.add(vec3(0.06, 0.06, 0.065)), band);
    mat.colorNode = col;
    materials.push(mat);
    return mat;
  }

  // ---------- chamferFrameMaterial: brushed metal edge ----------
  function chamferFrameMaterial() {
    const mat = new MeshPhysicalNodeMaterial({
      color: new THREE.Color(C.ink),
      roughness: 0.5,
      metalness: 0.45,
      clearcoat: 0.2,
      clearcoatRoughness: 0.35,
    });
    materials.push(mat);
    return mat;
  }

  // ---------- tickBar: signal-red accent bar ----------
  function tickBar() {
    const geo = new THREE.BoxGeometry(0.4, 0.05, 0.02);
    geometries.push(geo);
    const mat = new MeshStandardNodeMaterial({
      color: new THREE.Color(C.accent),
      emissive: new THREE.Color(C.accent),
      emissiveIntensity: 1.3,
      roughness: 0.6,
      metalness: 0.1,
    });
    materials.push(mat);
    return new THREE.Mesh(geo, mat);
  }

  // ---------- buildCell: shallow extruded slab with chamfer frame ----------
  function buildCell(w, h, x, y) {
    const cell = new THREE.Group();
    cell.position.set(x, y, 0);

    // chamfer body: slightly larger slab behind, brushed metal — reads as the 0.04u chamfer edge
    const frameGeo = new THREE.BoxGeometry(w, h, 0.06);
    geometries.push(frameGeo);
    const frame = new THREE.Mesh(frameGeo, chamferFrameMaterial());
    frame.position.z = 0;
    cell.add(frame);

    // face slab: inset by chamfer, carries the engineered gradient
    const faceGeo = new THREE.PlaneGeometry(w - 0.08, h - 0.08);
    geometries.push(faceGeo);
    const face = new THREE.Mesh(faceGeo, slabFaceMaterial());
    face.position.z = 0.035;
    cell.add(face);

    // tick bar top-left inside 0.5u padding
    const tick = tickBar();
    tick.position.set(-w / 2 + 0.5 + 0.2, h / 2 - 0.5 + 0.1, 0.06);
    cell.add(tick);

    root.add(cell);
    return cell;
  }

  // ---------- textBlocks: MSDF text via ctx.fontAtlas ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  function findText(role, fallback) {
    const hit = items.find((i) => i.role === role && !hit?._used);
    return hit?.text ?? fallback;
  }
  // deterministic order per spec manifest
  const t = items.map((i) => i.text);
  const captionTxt = t[0] ?? 'ATELIER METRICS / Q2 2026';
  const heroValTxt = t[1] ?? '0.002 mm';
  const heroLblTxt = t[2] ?? 'Case tolerance, CNC pass';
  const v2Txt = t[3] ?? '38 h';
  const l2Txt = t[4] ?? 'Power reserve, NA-01';
  const v3Txt = t[5] ?? '214';
  const l3Txt = t[6] ?? 'Components per calibre';

  function addText(parent, content, opts, x, y) {
    const obj = ctx.fontAtlas.createText(content, opts);
    obj.position.set(x, y, 0.07);
    parent.add(obj);
    return obj;
  }

  // ---------- layout ----------
  backdropStage();
  lightRig();

  // grid 5.5 x 3.5 centered at origin, 0.25 gutter
  // dominant left: 3.25 x 3.5 at x = -2.75 + 3.25/2 = -1.125
  const domCell = buildCell(3.25, 3.5, -1.125, 0);
  // right column x = 2.75 - 2.0/2 = 1.75; cells 2.0 x 1.625, gutter 0.25
  const topCell = buildCell(2.0, 1.625, 1.75, 0.9375);
  const botCell = buildCell(2.0, 1.625, 1.75, -0.9375);

  // header caption 0.5u above grid, left-aligned to x=-2.75
  const caption = ctx.fontAtlas.createText(captionTxt, {
    fontSize: 18,
    color: C.paper,
    align: 'left',
    letterSpacingPx: 2.2,
  });
  caption.position.set(-2.75, 1.75 + 0.5, 0.02);
  root.add(caption);

  // dominant cell copy — hero value is the single brightest element
  addText(domCell, heroValTxt, { fontSize: 124, color: C.paper, align: 'left' }, -3.25 / 2 + 0.5, 0.1);
  addText(domCell, heroLblTxt, { fontSize: 18, color: '#9aa2ad', align: 'left', letterSpacingPx: 1.4 }, -3.25 / 2 + 0.5, -0.5);

  // secondary cells
  addText(topCell, v2Txt, { fontSize: 68, color: C.paper, align: 'left' }, -1 + 0.5, 0.05);
  addText(topCell, l2Txt, { fontSize: 18, color: '#9aa2ad', align: 'left', letterSpacingPx: 1.4 }, -1 + 0.5, -0.35);
  addText(botCell, v3Txt, { fontSize: 68, color: C.paper, align: 'left' }, -1 + 0.5, 0.05);
  addText(botCell, l3Txt, { fontSize: 18, color: '#9aa2ad', align: 'left', letterSpacingPx: 1.4 }, -1 + 0.5, -0.35);

  // ---------- contact shadow under grid ----------
  (function contactShadow() {
    const geo = new THREE.PlaneGeometry(6.6, 4.4);
    geometries.push(geo);
    const mat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
    const d2 = uv().sub(0.5).length();
    mat.colorNode = vec3(0, 0, 0);
    mat.opacityNode = smoothstep(0.5, 0.15, d2).mul(0.5);
    materials.push(mat);
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.set(0.1, -0.15, -0.4);
    root.add(mesh);
  })();

  // ---------- entranceMotion: stagger-cards fade-up, dominant first ----------
  const cells = [domCell, topCell, botCell];
  const entrance = gsap.timeline();
  cells.forEach((cell, i) => {
    const targetY = cell.position.y;
    cell.position.y = targetY + 0.2;
    cell.scale.setScalar(0.001); // avoid pop; scale up with fade proxy
    entrance.to(
      cell.position,
      { y: targetY, duration: 0.5, ease: 'power2.out' },
      i * 0.08
    );
    entrance.to(
      cell.scale,
      { x: 1, y: 1, z: 1, duration: 0.5, ease: 'power2.out' },
      i * 0.08
    );
  });
  entrance.fromTo(
    caption.position,
    { y: 2.25 + 0.2 },
    { y: 2.25, duration: 0.5, ease: 'power2.out' },
    0
  );
  timelines.push(entrance);

  // ---------- interaction: press-down / weighted-settle ----------
  let pressTl = null;
  function pressCell(cell) {
    if (pressTl) pressTl.kill();
    pressTl = gsap.timeline();
    pressTl.to(cell.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(1.7)' });
    pressTl.to(cell.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.15, ease: 'power2.out' });
    pressTl.to(cell.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });
    timelines.push(pressTl);
  }

  // ---------- cinematic primitives from config ----------
  for (const p of config.cinematicPrimitives ?? []) {
    const fn = ctx.primitives[p.name];
    if (fn) primHandles.push(fn(root, p.params ?? {}));
  }

  // ---------- handlers + cleanup ----------
  root.userData.handlers = {
    pointerdown: () => pressCell(domCell),
    click: () => ctx.emit('metric-select', { id: 'case-tolerance' }),
  };

  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    primHandles.forEach((h) => h?.cleanup?.());
    geometries.forEach((g) => g.dispose());
    materials.forEach((m) => m.dispose());
  };

  return root;
}

