{"id":"text.value.3","where":"addText topCell v2Txt","how":"68px value in top secondary cell"},
{"id":"text.label.4","where":"addText topCell l2Txt","how":"18px mono label top cell"},
{"id":"text.value.5","where":"addText botCell v3Txt","how":"68px value in bottom secondary cell"},
{"id":"text.label.6","where":"addText botCell l3Txt","how":"18px mono label bottom cell"},
{"id":"color.background","where":"backdropStage","how":"stage gradient base #0b0b10"},
